import sys
sys.path.insert(0, "..")
import numpy as np
from floor_of_line import tables
T = tables()
s127 = ",".join(str(int(v)) for v in T[127])
s128 = ",".join(str(int(v)) for v in T[128])
open("RsqrtTable.lean", "w").write(
    "/- The estimate of rsqrtps on the AMD Ryzen 7 3800X, in units of 2^-13, for the 4096 groups of the\n"
    "    top 12 mantissa bits, exponent fields 127 and 128. Generated by gen_table.py from the live CPU. -/\n"
    "namespace RsqrtWitness\n\n"
    'def raw127 : String := "' + s127 + '"\n\n'
    'def raw128 : String := "' + s128 + '"\n\n'
    "end RsqrtWitness\n")
print("table written", len(s127), len(s128))
